import {
  Catch,
  HttpException,
  ArgumentsHost,
  HttpStatus,
} from '@nestjs/common';
import { BaseExceptionFilter } from '@nestjs/core';
import type { Request, Response } from 'express';
import { ExceptionResponse } from './interfaces/exception-response.interface';

@Catch(HttpException)
export class MesGenericErrorFilter extends BaseExceptionFilter {
  public static catch(exception: unknown, host: ArgumentsHost): void {
    const context = host.switchToHttp();
    const response = context.getResponse<Response>();
    const request = context.getRequest<Request>();
    // Determine the status code
    const status
      = exception instanceof HttpException
        ? exception.getStatus()
        : HttpStatus.INTERNAL_SERVER_ERROR;

    let message = 'An error occurred';
    let errorCode = 'UNHANDLED_EXCEPTION';
    if (exception instanceof HttpException) {
      const exceptionResponse = exception.getResponse();
      if (typeof exceptionResponse === 'string') {
        message = exceptionResponse;
      }
      else if (
        typeof exceptionResponse === 'object'
        && exceptionResponse !== null
      ) {
        message = (exceptionResponse as ExceptionResponse).message ?? message;
        errorCode = (exceptionResponse as ExceptionResponse).error ?? errorCode;
      }
    }
    else {
      message = (exception as Error).message || message;
    }

    // Default behavior for other exceptions
    response.status(status).json({
      body: request.body as unknown,
      errorCode,
      message,
      params: request.params,
      path: request.url,
      query: request.query,
      statusCode: status,
      timestamp: new Date().toISOString(),
    });
  }
}

import { InvokerOptions } from '@dapr/dapr';

/**
 * Builds options for Dapr invoker.
 * @returns - Options for Dapr invoker
 */
export function buildInvokeOptions(): InvokerOptions {
  const options: InvokerOptions = {};

  if (process.env.TOKEN != null && process.env.TOKEN !== '') {
    options.headers = { authorization: `Bearer ${process.env.TOKEN}` };
  }

  return options;
}

import { JobsLogContext } from '@mesx/common-lib';
import { HttpException, HttpStatus } from '@nestjs/common';
import { DaprClient, HttpMethod } from 'dapr-client';
import { buildInvokeOptions } from './build-invoke-options';
import { AppLogger } from '@/common/logger/app-logger';
import { RequestHeadersDto } from '@/dtos/request-headers.dto';

interface ParsedDaprError {
  status: number
  message: string
}

/**
 * Parses an error message returned from Dapr to extract the status code and error message.
 * @param errorMessage  - The error message returned from Dapr, which may be a JSON string containing 'status' and 'error_msg' fields.
 * @returns An object containing the parsed status code and error message. If parsing fails, defaults to a 500 status and the original error message.
 */
function parseDaprError(errorMessage: string): ParsedDaprError {
  let status = HttpStatus.INTERNAL_SERVER_ERROR;
  let message = errorMessage;

  try {
    const parsed: unknown = JSON.parse(errorMessage);
    if (
      typeof parsed === 'object'
      && parsed !== null
      && 'status' in parsed
      && typeof (parsed as Record<string, unknown>).status === 'number'
    ) {
      const parsedStatus = (parsed as Record<string, unknown>).status as number;
      if (parsedStatus >= 400 && parsedStatus < 600) {
        status = parsedStatus;
      }
    }
    if (
      typeof parsed === 'object'
      && parsed !== null
      && 'error_msg' in parsed
      && typeof (parsed as Record<string, unknown>).error_msg === 'string'
    ) {
      message = (parsed as Record<string, unknown>).error_msg as string;
    }
  }
  catch {
    // Not a JSON message, use defaults
  }

  return { message, status };
}

/**
 * Invokes a service using Dapr client.
 * @param serviceContext - Context for the service invocation, including Dapr client and logger.
 * @param serviceContext.context - The context for the service.
 * @param serviceContext.customLogger - The custom logger instance.
 * @param serviceContext.daprClient - The Dapr client instance.
 * @param requestContext - Context for the request, including service ID, method, HTTP method, data, and options.
 * @param requestContext.serviceAppId - The ID of the service to invoke.
 * @param requestContext.serviceMethod - The method to invoke on the service.
 * @param requestContext.method - The HTTP method to use for the invocation.
 * @param requestContext.data - The data to send with the request.
 * @param requestContext.options - Optional settings for the request, including headers and error handling.
 * @param requestContext.options.headers - Optional headers to include in the request.
 * @param errorHandling - Optional error handling settings.
 * @param errorHandling.throwIfError - Whether to throw an error if the invocation fails.
 * @param errorHandling.customError - A custom error to throw if the invocation fails.
 * @returns The response from the invoked service, or undefined if an error occurred and throwIfError is false.
 * @throws {Error} if the invocation fails and throwIfError is true.
 */
export async function invokeService<T>(
  serviceContext: {
    context: JobsLogContext
    customLogger: AppLogger
    daprClient: DaprClient
  },
  requestContext: {
    serviceAppId: string
    serviceMethod: string
    method: HttpMethod
    data?: object
    options?: {
      headers?: Record<string, unknown> | RequestHeadersDto
    }
  },
  errorHandling?: {
    throwIfError?: boolean
    customError?: Error
  },
): Promise<T | undefined> {
  const { context, customLogger, daprClient } = serviceContext;
  const {
    serviceAppId,
    serviceMethod,
    method,
    data,
    options,
  } = requestContext;

  const { headers } = options ?? {};

  try {
    const invokeOptions = headers ? { headers } : buildInvokeOptions();
    // Ensure content-type is set for requests with data
    if (data && method !== HttpMethod.GET && method !== HttpMethod.DELETE) {
      invokeOptions.headers ??= {};
    }

    const response = await daprClient.invoker.invoke(
      serviceAppId,
      serviceMethod,
      method,
      data ? { ...data } : undefined,
      invokeOptions,
    );
    return response as T;
  }
  catch (error: unknown) {
    const errorMessage = error instanceof Error ? error.message : String(error);
    const errorStack = error instanceof Error ? error.stack : undefined;

    customLogger.error(
      `Error in ${context.method}: ${errorMessage}`,
      errorStack,
    );

    if ((errorHandling?.throwIfError) ?? false) {
      if (errorHandling?.customError) throw errorHandling?.customError;

      const { message, status } = parseDaprError(errorMessage);
      throw new HttpException(message, status);
    }

    return undefined;
  }
}

import { Logger } from '@nestjs/common';

export class AppLogger extends Logger {
  public log(message: unknown): void {
    super.log(`${new Date().toISOString()} -- ${String(message)}`);
  }

  public error(message: unknown, stack?: string): void {
    super.error(`${new Date().toISOString()} -- ${String(message)}`, stack);
  }

  public warn(message: unknown): void {
    super.warn(`${new Date().toISOString()} -- ${String(message)}`);
  }

  public debug(message: unknown): void {
    super.debug(`${new Date().toISOString()} -- ${String(message)}`);
  }

  public verbose(message: unknown): void {
    super.verbose(`${new Date().toISOString()} -- ${String(message)}`);
  }
}

/**
 * Async sleep
 * @param timeout in ms
 */
export async function asyncSleep(timeout: number): Promise<void> {
  await new Promise((resolve) => {
    setTimeout(resolve, timeout);
  });
}

import { Injectable, OnModuleInit } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { AppLogger } from '@/common/logger/app-logger';

@Injectable()
export class AppConfigInitialConfigService implements OnModuleInit {
  private readonly logger = new AppLogger(AppConfigInitialConfigService.name);

  public constructor(private readonly configService: ConfigService) {}

  public onModuleInit(): void {
    this.checkConfiguration();
  }

  public get appConfigCachingTtl(): number {
    return this.configService.get<number>('appConfigCachingTtl') ?? 20_000;
  }

  public get appConfigEndpoint(): string {
    return this.configService.get<string>('appConfigEndpoint') ?? '';
  }

  private checkConfiguration(): void {
    const requiredConfigs = [
      { key: 'appConfigEndpoint', value: this.appConfigEndpoint },
    ];

    /*
     * Check mandatory fields
     */
    for (const config of requiredConfigs) {
      if (!config.value) {
        this.logger.error(`Missing configuration value for ${config.key}`);
        throw new Error(`Configuration error: ${config.key} is not set`);
      }
    }

    this.logger.log(
      'All required "App Config Initial Configuration" configurations are properly set',
    );
  }
}

