import { ResponseWrapper, STATUS_CODE, WrappedResponse } from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import { HttpMethod, DaprClient } from 'dapr-client';
import { BomDefinitionResponseDto } from './dtos/bom-definition-response.dto';
import { GetBomDefinitionsQueryDto } from './dtos/get-bom-definitions-query.dto';
import { buildMethodPath } from './helpers/build-method-path.helper';
import { invokeService } from '@/common/invokes/invoke-service';
import { AppLogger } from '@/common/logger/app-logger';
import { DaprConfigService } from '@/config/dapr/dapr-config.service';

@Injectable()
export class BomDefinitionService {
  private readonly logger = new AppLogger(BomDefinitionService.name);

  private readonly daprClient: DaprClient;

  private readonly targetAppId: string;

  public constructor(private readonly daprConfigService: DaprConfigService) {
    this.targetAppId
      = this.daprConfigService.masterApiAppId ?? 'mesx-master-api';
    this.daprClient = new DaprClient();
  }

  public async getBomDefinitionsByMaterialAndPlant(
    query: GetBomDefinitionsQueryDto,
  ): Promise<WrappedResponse<BomDefinitionResponseDto | undefined>> {
    const method = buildMethodPath('v1/isa95-bom-operations-model/bom-definitions', {
      materialDefinitionId: query.materialDefinitionId,
      plant: query.plant,
    });
    return (await invokeService<
      WrappedResponse<BomDefinitionResponseDto | undefined>
    >(
      { context: { service: 'BomDefinitionService', method: 'getBomDefinitionsByMaterialAndPlant' }, customLogger: this.logger, daprClient: this.daprClient },
      { method: HttpMethod.GET, serviceAppId: this.targetAppId, serviceMethod: method },
      { throwIfError: true },
    )) ?? ResponseWrapper.error(
      STATUS_CODE.NOT_FOUND,
      `BOM definitions not found for material ${query.materialDefinitionId} at plant ${query.plant}`,
    );
  }
}

