/**
 * Build a Dapr invoke method string from a base path and optional query params.
 * Dapr's invoker uses the path after /method/ as the service method name,
 * so query strings must be appended directly to the method string.
 * @param path Base URL path, e.g. 'isa95-material-model/material-definition'
 * @param parameters Optional query parameters to append.
 * @returns Full method string including query string when params are provided.
 */
export function buildMethodPath(
  path: string,
  parameters?: Record<string, string | number | boolean | undefined | Array<string | number | boolean>>,
): string {
  if (parameters === undefined) {
    return path;
  }

  const queryParts: Array<string> = [];

  for (const [key, value] of Object.entries(parameters)) {
    if (value === undefined) {
      continue;
    }

    if (Array.isArray(value)) {
      for (const item of value) {
        queryParts.push(`${encodeURIComponent(key)}=${encodeURIComponent(String(item))}`);
      }
    }
    else {
      queryParts.push(`${encodeURIComponent(key)}=${encodeURIComponent(String(value))}`);
    }
  }

  if (queryParts.length === 0) {
    return path;
  }

  return `${path}?${queryParts.join('&')}`;
}

