  public material?: string;

  /**
   * Optional equipment filter
   */
  @ApiProperty({
    description: 'Optional equipment filter',
    example: 'EQ01',
    required: false,
    type: String,
  })
  @IsOptional()
  @IsString()
  @MaxLength(8)
  public equipment?: string;

  /**
   * Pagination limit
