import { Module } from '@nestjs/common';
import { OperationDefinitionController } from './operation-definition.controller';
import { OperationDefinitionService } from './operation-definition.service';
import { DaprConfigModule } from '@/config/dapr/dapr-config.module';

@Module({
  controllers: [OperationDefinitionController],
  imports: [DaprConfigModule],
  providers: [OperationDefinitionService],
})
export class OperationDefinitionModule {}

import {
  ResponseWrapper,
  STATUS_CODE,
  WrappedResponse,
} from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import { DaprClient, HttpMethod } from 'dapr-client';
import { buildMethodPath } from '../bom-definition/helpers/build-method-path.helper';
import { GetFilterEquipmentQueryDto } from './dtos/get-filter-equipment-query.dto';
import { GetFilterMaterialsQueryDto } from './dtos/get-filter-materials-query.dto';
import { GetOperationDefinitionsQueryDto } from './dtos/get-operation-definitions-query.dto';
import { OperationDefinitionDetailsDto } from './dtos/operation-definition-details.dto';
import { OperationDefinitionTableRowDto } from './dtos/operation-definition-table-row.dto';
import { invokeService } from '@/common/invokes/invoke-service';
import { AppLogger } from '@/common/logger/app-logger';
import { DaprConfigService } from '@/config/dapr/dapr-config.service';

@Injectable()
export class OperationDefinitionService {
  private readonly logger = new AppLogger(OperationDefinitionService.name);

  private readonly daprClient: DaprClient;

  private readonly targetAppId: string;

  public constructor(private readonly daprConfigService: DaprConfigService) {
    this.targetAppId
      = this.daprConfigService.masterApiAppId ?? 'mesx-master-api';
    this.daprClient = new DaprClient();
  }

  public async getFilterMaterials(
    query: GetFilterMaterialsQueryDto,
  ): Promise<WrappedResponse<Array<{ code: string }> | undefined>> {
    const method = buildMethodPath(
      'v1/isa95-operation-model/operation-definitions/filter-materials',
      {
        equipment: query.equipment === '' ? undefined : query.equipment,
        plant: query.plant,
        search: query.search === '' ? undefined : query.search,
      },
    );

    return (
      (await invokeService<WrappedResponse<Array<{ code: string }> | undefined>>(
        {
          context: {
            method: 'getFilterMaterials',
            service: 'OperationDefinitionService',
          },
          customLogger: this.logger,
          daprClient: this.daprClient,
        },
        {
          method: HttpMethod.GET,
          serviceAppId: this.targetAppId,
          serviceMethod: method,
        },
        { throwIfError: true },
      ))
      ?? (ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'Unexpected server error',
      ))
    );
  }

  public async getFilterEquipment(
    query: GetFilterEquipmentQueryDto,
  ): Promise<WrappedResponse<Array<{ equipment: string }> | undefined>> {
    const method = buildMethodPath(
      'v1/isa95-operation-model/operation-definitions/filter-equipment',
      {
        material: query.material === '' ? undefined : query.material,
        plant: query.plant,
      },
    );

    return (
      (await invokeService<WrappedResponse<Array<{ equipment: string }> | undefined>>(
        {
          context: {
            method: 'getFilterEquipment',
            service: 'OperationDefinitionService',
          },
          customLogger: this.logger,
          daprClient: this.daprClient,
        },
        {
          method: HttpMethod.GET,
          serviceAppId: this.targetAppId,
          serviceMethod: method,
        },
        { throwIfError: true },
      ))
      ?? (ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'Unexpected server error',
      ))
    );
  }

  public async getOperationDefinitions(
    query: GetOperationDefinitionsQueryDto,
  ): Promise<WrappedResponse<Array<OperationDefinitionTableRowDto> | undefined>> {
    const method = buildMethodPath(
      'v1/isa95-operation-model/operation-definitions',
      {
        equipment: query.equipment === '' ? undefined : query.equipment,
        limit: query.limit,
        material: query.material === '' ? undefined : query.material,
        page: query.page,
        plant: query.plant,
        status: query.status === 'All' ? undefined : query.status,
      },
    );

    return (
      (await invokeService<
        WrappedResponse<Array<OperationDefinitionTableRowDto> | undefined>
      >(
        {
          context: {
            method: 'getOperationDefinitions',
            service: 'OperationDefinitionService',
          },
          customLogger: this.logger,
          daprClient: this.daprClient,
        },
        {
          method: HttpMethod.GET,
          serviceAppId: this.targetAppId,
          serviceMethod: method,
        },
        { throwIfError: true },
      ))
      ?? (ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'Unexpected server error',
      ))
    );
  }

  public async getOperationDefinitionDetails(
    operationId: number,
  ): Promise<WrappedResponse<OperationDefinitionDetailsDto | undefined>> {
    return (
      (await invokeService<
        WrappedResponse<OperationDefinitionDetailsDto | undefined>
      >(
        {
          context: {
            method: 'getOperationDefinitionDetails',
            service: 'OperationDefinitionService',
          },
          customLogger: this.logger,
          daprClient: this.daprClient,
        },
        {
          method: HttpMethod.GET,
          serviceAppId: this.targetAppId,
          serviceMethod: `v1/isa95-operation-model/operation-definitions/details/${operationId}`,
        },
        { throwIfError: true },
      ))
      ?? (ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'Unexpected server error',
      ))
    );
  }
}

