import { invokeService } from '@/common/invokes/invoke-service';
import { AppLogger } from '@/common/logger/app-logger';
import { DaprConfigService } from '@/config/dapr/dapr-config.service';

@Injectable()
export class OperationSegmentService {
  private readonly logger = new AppLogger(OperationSegmentService.name);
  private readonly daprClient: DaprClient;

  private readonly targetAppId: string;

  public constructor(private readonly daprConfigService: DaprConfigService) {
    this.targetAppId
      = this.daprConfigService.masterApiAppId ?? 'mesx-master-api';
    this.daprClient = new DaprClient();
  }

  public async getOperationSegments(
    query: GetOperationSegmentsQueryDto,
  ): Promise<WrappedResponse<Array<GroupedOperationSegmentsResultDto> | undefined>> {
    const method = buildMethodPath('v1/isa95-operation-model/operation-segments', {
      operationDefinitionId: query.operationDefinitionId,
      plant: query.plant,
      status: query.status === 'All' ? undefined : query.status,
    });

    return (
      (await invokeService<
        WrappedResponse<Array<GroupedOperationSegmentsResultDto> | undefined>
      >(
        {
          context: {
            method: 'getOperationSegments',
            service: OperationSegmentService.name,
          },
          customLogger: this.logger,
          daprClient: this.daprClient,
        },
        {
          method: HttpMethod.GET,
          serviceAppId: this.targetAppId,
          serviceMethod: method,
        },
        { throwIfError: true },
      ))
      ?? ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'Unexpected server error',
      )
    );
  }

  public async getOperationSegmentsByMaterial(
    query: GetOperationSegmentsByMaterialQueryDto,
  ): Promise<WrappedResponse<Array<GroupedOperationSegmentsResultDto> | undefined>> {
    const method = buildMethodPath(
      'v1/isa95-operation-model/operation-segments/by-material',
      {
        material: query.material.trim(),
        plant: query.plant,
        status: query.status === 'All' ? undefined : query.status,
      },
    );

    return (
      (await invokeService<
        WrappedResponse<Array<GroupedOperationSegmentsResultDto> | undefined>
      >(
        {
          context: {
            method: 'getOperationSegmentsByMaterial',
            service: OperationSegmentService.name,
          },
          customLogger: this.logger,
          daprClient: this.daprClient,
        },
        {
          method: HttpMethod.GET,
          serviceAppId: this.targetAppId,
          serviceMethod: method,
        },
        { throwIfError: true },
      ))
      ?? ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'Unexpected server error',
      )
    );
  }

  public async getOperationSegmentDetails(
    operationNumber: string,
  ): Promise<WrappedResponse<OperationSegmentDetailsDto | undefined>> {
    return (
      (await invokeService<
        WrappedResponse<OperationSegmentDetailsDto | undefined>
      >(
        {
          context: {
            method: 'getOperationSegmentDetails',
            service: OperationSegmentService.name,
          },
          customLogger: this.logger,
          daprClient: this.daprClient,
        },
        {
          method: HttpMethod.GET,
          serviceAppId: this.targetAppId,
          serviceMethod: `v1/isa95-operation-model/operation-segments/${encodeURIComponent(operationNumber)}`,
        },
        { throwIfError: true },
      ))
      ?? ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'Unexpected server error',
      )
    );
  }
}

